<?php
declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/layout.php';
$user=require_admin();$rows=db()->query("SELECT t.*,u.name,u.email,s.symbol FROM Transactions t JOIN Users u ON u.user_id=t.user_id JOIN Stocks s ON s.stock_id=t.stock_id ORDER BY t.transaction_id DESC")->fetchAll();
$body='<div class="table-card"><table class="table table-hover"><thead><tr><th>ID</th><th>Investor</th><th>Stock</th><th>Type</th><th>Quantity</th><th>Price</th><th>Amount</th><th>Date</th></tr></thead><tbody>';foreach($rows as$r){$body.='<tr><td>'.(int)$r['transaction_id'].'</td><td>'.e($r['name']).'</td><td><strong>'.e($r['symbol']).'</strong></td><td>'.e($r['transaction_type']).'</td><td>'.(int)$r['quantity'].'</td><td>₹'.number_format((float)$r['price'],2).'</td><td>₹'.number_format((float)$r['total_amount'],2).'</td><td>'.e((string)$r['transaction_date']).'</td></tr>';}$body.='</tbody></table></div>';render_layout('All Transactions',$body,$user,true);
